/**
 @function
 currencyKeystroke(positiveOnly, wholeDigits)

 @description
 Apply numerical formatting on a keystroke by keystroke basis.<br>
 Default format is (-)99999999999.99<br>
 IE. A total of 14 characters is allowed: 11 whole number digits,
 a decimal point, and 2 fractional digits.  The negative sign (-) is optional.

 @param {Boolean} positiveOnly (optional) 	- If negatives are not allowed set this to true.
 @param {Number} wholeDigits (optional) 	- Set this to the number of digits allowed before
 									the decimal

 @example
 Examples:
 currencyKeystroke();           
 - default settings.  Negatives are allowed. 11 digits accepted before the decimal.

 currencyKeystroke(true);
 - Negatives not allowed. 11 digits accepted before the decimal.

 currencyKeystroke(true, 7);
 - Negatives not allowed. 7 digits accepted before the decimal.

 currencyKeystroke(false, 9);
 - Negatives are allowed. 9 digits accepted before the decimal. 

 Last Modified: 
 Feb 11, 2011 	PDI000    - Initial version
 Nov 08, 2011	PDI000    - Return boolean
 Jan 18, 2012	PDI000    - Check for French locale and set the regular expression 
                            accordingly.
 Jan 19, 2012	PDI000    - For French locale set the regular expression to Allow 
                            '.' or ',' to be entered as the decimal point.

 */

function currencyKeystroke(positiveOnly, wholeDigits)
{
	//var positiveOnly=true;
	var regExpStr;
	if (this.locale == "fr_CA")
	{
		regExpStr = "\\d{0,11}\\[,.]\\d{0,2}|\\d{0,11}";
	}
	else
	{
		regExpStr = "\\d{0,11}\\.\\d{0,2}|\\d{0,11}";	
	}

	if (wholeDigits)
	{
		if (this.locale == "fr_CA")
		{
			regExpStr = "\\d{0," + wholeDigits + "}[,.]\\d{0,2}|\\d{0," + wholeDigits + "}";
		}
		else
		{
			regExpStr = "\\d{0," + wholeDigits + "}\\.\\d{0,2}|\\d{0," + wholeDigits + "}";
		}
	}

	if (!positiveOnly)
	{
		var pipePos = regExpStr.indexOf("|");
		var sub1 = regExpStr.substring(0, pipePos + 1);
		var sub2 = regExpStr.substring(pipePos + 1);

		regExpStr = "-{0,1}" + sub1 + "-{0,1}" + sub2;
	}

	if (DEBUG)console.println("In currencyKeystroke - regExpStr: " + regExpStr );	

	var codeMatchNumber = new RegExp(regExpStr);
	var totalVal = xfa.event.fullText;

	if (DEBUG)console.println("In currencyKeystroke - Field: " + this.name + ", Event: " + xfa.event.name + ", fullText=" + xfa.event.fullText);	
	if (DEBUG)console.println("In currencyKeystroke - locale name: " + this.locale );

	//xfa.host.messageBox(totalVal);
	if (totalVal != totalVal.match(codeMatchNumber))
	{
		//xfa.host.messageBox("unacceptable character");
		xfa.event.change = "";
		return false;
	}

	return true;
}


/**
 @function
 numericKeystroke(positiveOnly, wholeDigits)

 @description
 Apply numerical formatting on a keystroke by keystroke basis.<br>
 Default format is (-)99999999<br>
 IE. A total of 8 whole number digits are allowed.

 @param {Boolean} positiveOnly (optional) 	- If negatives are not allowed set this to true.
 @param {Number} wholeDigits (optional) 	- Set this to the number of digits allowed.

 @example
 Examples:
 numericKeystroke();	
 - default settings.  Negatives are allowed. 8 digits allowed.

 numericKeystroke(true);
 - Negatives not allowed. 8 digits allowed.

 numericKeystroke(true, 7);	
 - Negatives not allowed. 7 digits allowed.

 numericKeystroke(false, 9);
 - Negatives are allowed. 9 digits allowed. 

 Last Modified: 
 May 09, 2011 	PDI000    Initial version
 Nov 08, 2011	PDI000    Return boolean

 */
function numericKeystroke(positiveOnly, wholeDigits)
{
	//var positiveOnly=true;
	var regExpStr = "\\d{0,8}";

	if (wholeDigits)
	{
		regExpStr = "\\d{0," + wholeDigits + "}";
	}

	if (!positiveOnly)
	{	
		regExpStr = "-{0,1}" + regExpStr;
	}

	var codeMatchNumber = new RegExp(regExpStr);
	var totalVal = xfa.event.fullText;	

	if(DEBUG) console.println("In numericKeystroke - Field: " + this.name + ", fullText=" + xfa.event.fullText + ", match: " + totalVal.match(codeMatchNumber) + ", totlVal: " + totalVal);	

	//xfa.host.messageBox(totalVal);
	if (totalVal != totalVal.match(codeMatchNumber))
	{
		//xfa.host.messageBox("unacceptable character");
		xfa.event.change = "";
		return false;
	}

	return true;
}


/**
 @function
 floatKeystroke(positiveOnly, wholeDigits, fractionalDigits)

 @description
 Apply numerical formatting on a keystroke by keystroke basis.<br>
 Default format is (-)99999999.99999<br>
 IE. A total of 14 characters is allowed: 8 whole number digits,
 a decimal point, and 5 fractional digits.  The negative sign (-) is optional.

 @param {Boolean} positiveOnly (optional) 	- If negatives are not allowed set this to true.
 @param {Number} wholeDigits (optional) 	- Set this to the number of digits allowed before
 									the decimal
 @param {Number} fractionalDigits (optional) 	- Set this to the number of digits allowed after
 									the decimal


 @example
 Examples:
 floatKeystroke();           
 - default settings.  Negatives are allowed. 8 digits before the decimal. 5 digits after.

 floatKeystroke(true);
 - Negatives not allowed.

 floatKeystroke(true, 7, 3);
 - Negatives not allowed. 7 digits accepted before the decimal. 3 digits after.

 Last Modified: 
 Feb 11, 2011 	PDI000    - Initial version
 Jan 03, 2014   PDI000    - Handle 0 fractional digits

 */

function floatKeystroke(positiveOnly, wholeDigits, fractionalDigits)
{
	//var positiveOnly=true;
	var regExpStr;
	if (this.locale == "fr_CA")
	{
		regExpStr = "\\d{0,8}\\[,.]\\d{0,5}|\\d{0,8}";
	}
	else
	{
		regExpStr = "\\d{0,8}\\.\\d{0,5}|\\d{0,8}";	
	}

	var nFractionalLength = 5;	
	if (typeof fractionalDigits!= "undefined")
	{
		nFractionalLength = fractionalDigits;
	}

	if (wholeDigits)
	{
		if (this.locale == "fr_CA")
		{
			if (nFractionalLength == 0)
			{
				regExpStr = "\\d{0," + wholeDigits + "}";
			}
			else
			{
				regExpStr = "\\d{0," + wholeDigits + "}[,.]\\d{0," + nFractionalLength + "}|\\d{0," + wholeDigits + "}";
			}
		}
		else
		{
			if (nFractionalLength == 0)
			{
				regExpStr = "\\d{0," + wholeDigits + "}";	
			}
			else
			{
				regExpStr = "\\d{0," + wholeDigits + "}\\.\\d{0," + nFractionalLength + "}|\\d{0," + wholeDigits + "}";
			}
		}
	}

	if (!positiveOnly)
	{
		var pipePos = regExpStr.indexOf("|");
		var sub1 = regExpStr.substring(0, pipePos + 1);
		var sub2 = regExpStr.substring(pipePos + 1);

		regExpStr = "-{0,1}" + sub1 + "-{0,1}" + sub2;
	}

	if (DEBUG)console.println("In floatKeystroke- regExpStr: " + regExpStr );	

	var codeMatchNumber = new RegExp(regExpStr);
	var totalVal = xfa.event.fullText;

	if (DEBUG)console.println("In floatKeystroke- Field: " + this.name + ", Event: " + xfa.event.name + ", fullText=" + xfa.event.fullText);	
	if (DEBUG)console.println("In floatKeystroke- locale name: " + this.locale );

	if (totalVal != totalVal.match(codeMatchNumber))
	{
		xfa.event.change = "";
		return false;
	}

	return true;
}



/**
 @function
 getAcrobatHLColor()

 @description
 Reformats the Acrobat Highlight Color into XFA's RGB format.<br>
 So if Acrobat's Highlight colour is ["RGB",255,128,64] the returned value<br>
 would be "255,128,64".

 @returns {String}  the Acrobat Highlight Color in XFA's RGB format.

 @example

 Last Modified: 
 May 09, 2011 	PDI000    Initial version

 */
function getAcrobatHLColor()
{
	var aAcroColor = app.runtimeHighlightColor; // returns an array: ["RGB",R,G,B] (RGB value) or ["G",G] (gray value)

	// In the color array, the red, green and blue components are represented by values between 0 (no color) and 1 (full color).
	// We want the color represented as values between 0 (no color) and 255 (full color).

	if (aAcroColor[0] == "RGB")
	{
		// RGB value -- straight-forward
		return Math.round(aAcroColor[1] * 255) + "," + Math.round(aAcroColor[2] * 255) + "," + Math.round(aAcroColor[3] * 255);
	}
	else if (aAcroColor[0] == "G")
	{
		// Gray value -- apply same intensity to all components
		return Math.round(aAcroColor[1] * 255) + "," + Math.round(aAcroColor[1] * 255) + "," + Math.round(aAcroColor[1] * 255);
	}
	else
	{
		// don't know how to translate color into RGB
		return "";
	}
}



/**
 @function
 getFormatString(oField)

 @description
 Get the edit pattern of the given field. The edit pattern determines how the data should be entered.

 @param {Node} 		oField				 	- the object to examine.

 @returns {String} The edit pattern format string of the field.  So if the edit pattern is date{YYYYMMDD} the 
		return value is YYYYMMDD.

 @example		
 Examples:
 getFormatString(oField);	- default settings.

 Last Modified: 
 Nov 18, 2011    PDI000    Initial version

*/
function getFormatString(oField)
{
	// get the field picture pattern
	var sPic = new String(oField.ui.picture.value);

	if(CoreFunctions.DEBUG) console.println("(oYo) format string is " + sPic.substring(sPic.indexOf("{") + 1, sPic.indexOf("}")));

	return sPic.substring(sPic.indexOf("{") + 1, sPic.indexOf("}"));

}

/**
 @function
 isRequired(oField)

 @description
 Return true if the field is "required" and doesn't hsve a value.

 @param {Node} oField	- the object to check.

 @returns {Boolean} true if the field is empty and mandatory

 @example
 Examples:
 isRequired(node);	

 Last Modified: 
 Feb 02, 2011    PDI000    Initial version
 Jan 10, 2012    PDI000    Add check for a single space value if the field is a choicelist

*/

function isRequired(oField)
{
	var bRet = false;
	// if the field is hidden or resides in a hidden sub form then it can't be required
	if (isHidden(oField) || isReadOnly(oField))
	{
		bRet = false;
	}
	else
	{		
		if (DEBUG && oField)
		{
			console.println("V^V^V In isrequired. For " + oField.name + ", nulltest = " + oField.validate.nullTest);
		}
		if (DEBUG && oField.rawValue)
		{
			console.println("V^V^V In isrequired. rawValue = |" + oField.rawValue + "|");
			console.println("V^V^V In isrequired. rawValue length = " + oField.rawValue.length);
		}

		if (oField.validate.nullTest == "error" && (oField.rawValue == null || oField.rawValue.length == 0))
		{
			bRet = true; // mandatory field
		}
		// If the field's parent is an exclusion group, the exclusion group's mandatory setting applies to all fields it contains.
		else if (oField.parent.className == "exclGroup" && oField.parent.validate.nullTest == "error" && (oField.parent.rawValue == null || oField.parent.rawValue.length == 0))
		{
			bRet = true; // parent is a mandatory exclusion group (e.g. radio button list)
		}
		else if (oField.ui.oneOfChild.className == "choiceList"  && oField.validate.nullTest == "error" && oField.rawValue == " ")
		{
			bRet = true; // choicelist
		}
		else if (oField.ui.oneOfChild.className == "checkButton" && oField.validate.nullTest == "error")
		{
			// Check boxes always have a default value (so it won't be null neither will it be an empty string).
			// If a check box is mandatory, we'll assume that means it's value should either be "on" or "neutral" but not "off".
			// (Note that while check boxes can't be made mandatory via Designer's UI, they can be via script: See the Initialize script of the
			// CheckBox3 field.)

			// By definition (in the XFA 2.2 spec), the "off" value is the second value in the first <items> child node.

			var oItemsList = oField.resolveNodes("#items"); // note the "#" prefix to access the <items> child nodes explicitly

			if (oItemsList.length > 0)
			{
				var oValueList = oItemsList.item(0).nodes;

				if (oValueList.length > 1)
				{
					var sOffValue = oValueList.item(1).value;

					if (oField.rawValue == sOffValue)
						bRet = true; // found a mandatory check box whose value is still set to "off"
				}
			}
		}
	}

	return bRet;
}



/**
 @function
 postalCodeKeystroke(sPCIn)

 @description  
 Check the passed in string to see if it matches a Canadian Postal Code 

 @param {String} sPCIn		The postal code string that is being examined.

 @returns {Boolean}	true if format is good, otherwise false.

 @example
 Examples:
 postalCodeKeystroke(oNode);	

 Last Modified: 
 Apr 05, 2011    PDI000      Initial version
 Apr 13, 2011    PDI000      No need to pass in the change, just use xfa.event values.
 Jul 08, 2011    PDI000      Ignore anything after 6 characters.

*/
function postalCodeKeystroke(sFull, sChange)
{
	var sFull = xfa.event.fullText;
	var sChange = xfa.event.change; 

	if(DEBUG) console.println("----- sFull = " + sFull);
	if(DEBUG) console.println("----- sChange = " + sChange);
	var nLen = sFull.length;
	if(DEBUG) console.println("----- nLen = " + nLen);

	if (nLen > 6)
	{
		xfa.event.change = "";
	 	return false;
	}

	var sRegExp = "[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\d[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\s{0,1}\\d[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\d";

	switch (nLen)
	{
		case 1:
			sRegExp = "[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]";
			break;
		case 2:
			sRegExp = "[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\d";
			break;
		case 3:
			sRegExp = "[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\d[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]";
			break;
		case 4:
			sRegExp = "[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\d[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\s{0,1}\\d";
			break;
		case 5:
			sRegExp = "[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\d[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\s{0,1}\\d[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]";
			break;
		case 6:
		//case 7:
			sRegExp = "[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\d[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\s{0,1}\\d[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\\d";
			break;
	}

	//sRegExp = "[AaBbCcEeGgHhJjKkLlMmNnPpRrSsTtVvXxYy]\\d[AaBbCcEeGgHhJjKkLlMmNnPpRrSsTtVvWwXxYyZz]\\s{0,1}\\d[AaBbCcEeGgHhJjKkLlMmNnPpRrSsTtVvXxYyZz]\\d";

	var oRegEx = new RegExp(sRegExp);	

	if(DEBUG) console.println("----- regEx = " + oRegEx );
	if(DEBUG) console.println("----- match = " + sFull.match(oRegEx ));

	if (sFull != sFull.match(oRegEx ))
	{
		xfa.event.change = "";
		return false;
	}
	return true;
}



/**
 @function
 requiredFieldAlert(oNode)

 @description
 If the given field is required and has no value, alert the user and set focus to the field. 

 @param {Node} 	oNode      The object that is being examined to see if it is required.

 @returns {Boolean} true if an alert was sent, otherwise false

 @example
 Examples:
 requiredFieldAlert(oNode);	

 Last Modified: 
 Feb 02, 2011 	PDI000      Initial version
 Mar 09, 2011	PDI000      Added a check for rich text which is found in the exData node.
 May 10, 2011	PDI000      Change the message box call so that title of the pop-up
                            is Champ Obligatoire or Mandatory Field.
 Oct 21, 2011	PDI000      Check the Form Variable LANGUAGE to set the correct language
                            for the alert message.
 Jan 13, 2012	PDI000      Look for rich text caption before plain text caption.  When 
                            there is no plain text caption an erroneous value is returned.
*/
function requiredFieldAlert(oField)
{
	if (isRequired(oField))
	{
		//console.println("||requiredFieldAlert|| speak = " + oField.assist.speak.value + " tooltip = " + oField.assist.toolTip.value + " name = " + oField.name); 
		var alertText = oField.assist.speak.value;
		if (alertText == "")
			alertText = oField.assist.toolTip.value;
		if (alertText == "")
		{
			if(oField.caption.value.resolveNode("exData") != null)
				alertText = oField.caption.value.resolveNode("exData").value;			
		}
		if (alertText == "")
		{
			if(oField.caption.value.resolveNode("#text") != null)
				alertText = oField.caption.value.resolveNode("#text").value;
		}
		if (alertText == "")
			alertText = oField.name;

		try
		{
			if (LANGUAGE.value.toLowerCase() == FRENCH.toLowerCase())
				xfa.host.messageBox(alertText, "Champ Obligatoire");
			else if (LANGUAGE.value.toLowerCase() == ENGLISH.toLowerCase())
				xfa.host.messageBox(alertText, "Mandatory Field");
			else
				xfa.host.messageBox("The LANGUAGE Form Variable value " + LANGUAGE.value + " is not recognized.\n\nPlease use recognized values only, such as " +
				CoreFunctions.ENGLISH + " or " + CoreFunctions.FRENCH + ".", "Language Setting Error");				

		}
		catch (err)
		{
			xfa.host.messageBox(err + "\n\nPlease use LANGUAGE as the Form Variable name.", "Javascript Exception");
			return false;
		}	
		xfa.host.setFocus(oField.somExpression);
		return true;
	}

	return false;
}

/**
 @function
 requiredFields(oNode)

 @description  
 Recursively check for required fields that have no value using the passed in node as a<br>
 starting point.

 @param {Node} 	oNode      - The root node from which the search for required fields will begin.

 @returns {Boolean}  the number of fields found. This should always be 1 or 0 because
                     the function returns as soon as a required field is found.

 @example
 Examples:
 var nCount = requiredFields(FormNode);	
 - looks for required fields beneath the FormNode object.

 Last Modified: 
 Feb 2, 2011    PDI000    Initial version

*/

function requiredFields(oNode)
{
	var nNumRequired = 0;

	if (oNode.className == "exclGroup" || oNode.className == "subform"  || oNode.className == "subformSet" || oNode.className == "area")
	{
		// Look for child fields.

		for (var i = 0; i < oNode.nodes.length; i++)
		{
			var oChildNode = oNode.nodes.item(i);
			if(requiredFields(oChildNode))
				return 1;
		}
	}
	else if (oNode.className == "field")
	{
		switch (oNode.ui.oneOfChild.className)
		{
			case "button":				
			case "checkButton":			
			case "choiceList":	
			case "dateTimeEdit":
			case "imageEdit":
			case "numericEdit":			
			case "passwordEdit":			
			case "textEdit":			
			case "signature":
			case "barcode":
				if (requiredFieldAlert(oNode))
				{
					nNumRequired++;
				}
				break;

			default:
				// unknown field type
				break;
		}
	}

	return nNumRequired;
}


/**
 @function
 restoreAll(oNode)

 @description
 Clear all fields in the form.

 @example
 Example:
 restoreAll(oNode);						

 Last Modified: 
 Feb 03, 2011    PDI000    Initial version

*/
function restoreAll(oNode)
{
	if(xfa.host.messageBox("Do you want to clear all form fields?", "Reset Form?",2,2)==4)
	{ 
		xfa.host.resetData(),
		xfa.form.remerge();
	}
}


/**
 @function
 showDateValidation (sFormat)

 @description

 Validate the current keystroke on the a date field.

 @param {String} 	oField		- the date field.

 @example 
 Examples:
 showDateValidation (CoreFunctions.YYYYMMDD); //Show the validation message for the YYYYMMDD format
 showDateValidation (CoreFunctions.YYYYMM); //Show the validation message for the YYYYMM format

 Last Modified: 
 Nov 18, 2011    PDI000     Initial version

*/
function showDateValidation (sFormat)
{
	// get the format string
	if(!sFormat)
		sFormat = getFormatString(oField);

	if (LANGUAGE.value.toLowerCase() == ENGLISH.toLowerCase())	// Add the language suffix based on the global variable
			sMsgData = sFormat + CoreMessages.LANG_EN;
	//else (LANGUAGE.value.toLowerCase() == FRENCH.toLowerCase())
	else
			sMsgData = sFormat + CoreMessages.LANG_FR;

	if (CoreFunctions.DEBUG) 
		console.println("*&*&*&*& in showDateValidation: sMsgData = " + sMsgData);

	var sDateFormat = DateFormatArray[sMsgData][0];		
	var sampleFormat = DateFormatArray[sMsgData][1];
	var sampleString = DateFormatArray[sMsgData][2];

	if (CoreFunctions.DEBUG) 
		console.println("*&*&*&*& in showDateValidation: " + sampleFormat + ", " + sampleString);

	xfa.host.messageBox(CoreMessages.getMessage("M00023", sDateFormat.length, sampleFormat, sampleString), CoreMessages.getTitle("M00002"),1,0);

}


