/**
 @function
 validateKeystrokeCurrency(oField, nDigits, positiveOnly) (Deprecated)

 @description
 Validate the current keystroke on a currency field. (Deprecated) Instead, use validateKeystrokeFloat().
 For example,
 validateKeystrokeFloat(this, 13, 2, true, CoreFunctions.FLOAT_CURRENCY);

 @param {Node} oField                     - the currency field.
 @param {Number} nDigits                  - (optional) the number of digits allowed before the decimal. Default is 13.
 @param {Boolean} positiveOnly(optional)  - If negatives are not allowed set this to true.

 @example
 Examples:
 validateKeystrokeCurrency(this);           - default settings.
 validateKeystrokeCurrency(this, 11);       - allow 11 digits before the decimal.
 validateKeystrokeCurrency(this, 9, false);	- allow 9 digits before the decimal. Allow negative
                                              numbers	

 Last Modified: 
 Nov 18, 2011 	PDI000      Initial version
 Nov 28, 2011	PDI000      Use the change event's newtext and prevText to detect overrun
 Jan 19, 2012	PDI000      Set validation message for French to indicate that ',' or '.'
                            is allowed for the decimal point.
 Feb 03, 2012	PDI000      Add a parameter to indicate the number of digits before the
                            decimal.
 Feb 15, 2012	PDI000      Add a positiveOnly parameter
 Feb 15, 2012	PDI000      Quiet the validation by limiting the overflow message.
 Feb 16, 2012	PDI000      Use M00027 for improved validation message.
 Jun 25, 2012   PDI000      Check for a change that is greater than 1 character in order
                            validate a pasted change.
 Aug 28, 2013   PDI000      Call out to validateKeyStrokeFloat() to do the main processing.

*/
function validateKeystrokeCurrency(oField, nDigits, positiveOnly)
{
	if(DEBUG) console.println("$$$ In validateKeystrokeCurrency. Field: |" + oField.name + "|, nDigits: |" + nDigits + "|, posOnly: |" + positiveOnly + "|");
	var nLength = 13;	//default number of digits before the decimal point is 13

	var bPosOnly = true;	
	if (positiveOnly!=undefined)	// if there's a positiveOnly parameter set our local variable
	{
		bPosOnly = positiveOnly;	
	}

	if (nDigits)
	{
		nLength = nDigits;
	}

	validateKeystrokeFloat(oField, nLength, 2, bPosOnly, FLOAT_CURRENCY);	

}


/**
 @function
 validateKeystrokeNumeric(oField, nDigits, positiveOnly, sNumType)

 @description
 Validate the current keystroke on a numeric field.

 @param {Node} oField                     - the numeric field.
 @param {Number} nDigits                  - (optional) the number of digits allowed. Default is 8.
 @param {Boolean} positiveOnly            - (optional) If negatives are not allowed set this to true. Default is false
 @param {String} sNumType                 - (optional) One of "SIN" (Social insurance number), "ZIP" (Zip code), or
                                            "GENERAL" (unspecified). Default is "GENERAL". This determines the message 
                                            given to the user on a keystroke fail. Constants are defined for convenience:
                                            CoreFunctions.NUM_SIN
                                            CoreFunctions.NUM_ZIP
                                            CoreFunctions.NUM_GENERAL

 @example
 Examples:
 validateKeystrokeNumeric(this);           // default settings.
 validateKeystrokeNumeric(this, 11);       // allow 11 digits.
 validateKeystrokeNumeric(this, 9, false);	// allow 9 digits. Allow negative numbers	
 validateKeystrokeNumeric(this, 9, true, CoreFunctions.NUM_ZIP);	// allow 9 digits. Positive-only. Error response is
                                                                    // specific for Zip Codes	

 Last Modified: 
 Jun 07, 2012  PDI000      Initial version
 Jun 25, 2012  PDI000      Check for a change that is greater than 1 character in order
                           validate a pasted change.
 Oct 09, 2013  PDI000      Handle error messaging for positive-only state.
 Oct 16, 2013  PDI000      Add handling for sNumType

*/
function validateKeystrokeNumeric(oField, nDigits, positiveOnly, sNumType)
{
	if(DEBUG) console.println("$$$ In validateKeystrokeNumeric. Field: |" + oField.name + "|, nDigits: |" + nDigits + "|, posOnly: |" + positiveOnly + "|");
	if(DEBUG) console.println("$$$$$ change: [" + xfa.event.change + "], len: [" + xfa.event.change.length + "], new: [" + xfa.event.newText + "]");	

	var bPosOnly = true;	
	if (positiveOnly!=undefined)	// if there's a positiveOnly parameter set our local variable
	{
		bPosOnly = positiveOnly;	
	}

	var nLength = 8;	//default number of digits is 8	
	if (nDigits != undefined)
	{
		nLength = nDigits;
	}

	var sType = CoreFunctions.NUM_GENERAL; // set type default
    if (sNumType != undefined)
    {
    	sType = sNumType;
    }

	var sMsg = "";

	switch (sType)
	{
		case "ZIP":			// Zip Code
			sMsg = CoreMessages.getMessage("M00007") + " " + CoreMessages.getMessage("M00035");
			break;
		case "GENERAL":			// default
		    sMsg = CoreMessages.getMessage("M00033", nLength);
			if (bPosOnly)
			{	
				sMsg = CoreMessages.getMessage("M00047", nLength);
			}
			break;
	}

	if (xfa.event.change != "")
	{
	    if (xfa.event.change.match(/[-]|[0-9]/) == null
	    	|| (bPosOnly == true && xfa.event.change.match(/[-]/) != null))
	    {
	        xfa.event.change = "";

	        xfa.host.messageBox(sMsg, CoreMessages.getTitle("M00033"),1,0);
	    }
	 	else if(xfa.event.change.length == 1)
	 	{
	 		if(!CoreFunctions.numericKeystroke(bPosOnly, nLength))
			{
				// Removing this message to quiet down the keystroke validation			
				//xfa.host.messageBox(CoreMessages.getMessage("M00020", nLength), CoreMessages.getTitle("M00020"),1,0);
			}
		}
		else if(xfa.event.change.length > 1)		
		{
			if(!CoreFunctions.numericKeystroke(bPosOnly, nLength))
			{		
				xfa.host.messageBox(sMsg, CoreMessages.getTitle("M00033"),1,0);
			}
		}		
	}
}



/**
 @function
 validateKeystrokeFloat(oField, nDigits, nFractionalDigits, positiveOnly, sFloatType)

 @description
 Validate the current keystroke on a floating point numeric field.

 @param {Node} oField                     - the currency field.
 @param {Number} nDigits                  - (optional) the number of digits allowed before the decimal. Default is 8.
 @param {Number} nFractionalDigits        - (optional) the number of digits allowed after the decimal. Default is 5.
 @param {Boolean} positiveOnly            - (optional) If negatives are not allowed set this to true.
 @param {String} sFloatType               - (optional) One of "1" (currency), "2" (percentage), "3" (negative
                                            with parenthesis), "4" standard float). Default is "4". This determines
                                            the message given to the user on a keystroke fail. Constants are defined
                                            for convenience:
                                            CoreFunctions.FLOAT_CURRENCY
                                            CoreFunctions.FLOAT_PERCENT
                                            CoreFunctions.FLOAT_NEG_PAREN
                                            CoreFunctions.FLOAT_GENERAL


 @example
 Examples:
 validateKeystrokeFloat(this);              - default settings.
 validateKeystrokeFloat(this, 5, 4, true);  - allow 5 digits before the decimal. 4 digits after. Positive only
 validateKeystrokeFloat(this, 3, 3, false, CoreFunctions.FLOAT_PERCENT);	
                                            - allow 3 digits before the decimal. 3 digit after. Allow negatives.
                                              Generate error message for Percentage field.

 Last Modified: 
 Aug 09, 2013 	PDI000      Initial version
 Aug 27, 2013   PDI000      Add Float Type parameter
 Oct 09, 2013   PDI000      Handle error messaging for positive-only state.
 Jan 03, 2014   PDI000      Handle 0 fractional digits

*/
function validateKeystrokeFloat(oField, nDigits, nFractionalDigits, positiveOnly, sFloatType)
{
	if(DEBUG) console.println("$$$ In validateKeystrokeFloat. Field: " + oField.name + ", nDigits: " + nDigits + ", nFractionalDigits: " + nFractionalDigits +  ", posOnly: " + positiveOnly + ", type: " + sFloatType);
	var nLength = 8;	// default number of digits before the decimal point is 8
	var nFractionalLength = 5; // default number of fractional digits is 5

	var bPosOnly = true;	
	if (positiveOnly!=undefined)	// if there's a positiveOnly parameter set our local variable
	{
		bPosOnly = positiveOnly;	
	}

	if (nDigits)
	{
		nLength = nDigits;
	}

	if (typeof nFractionalDigits != "undefined")
	{
		nFractionalLength = nFractionalDigits;
	}

//	var sNines = "99999999999999999999";
//	var sDigitsPattern = sNines.substring(0, nLength);
//	var sFractionalDigitsPattern = sNines.substring(0, nFractionalLength);

	// check for form language and set the format string accordingly
//	var sFormat = sDigitsPattern + "." + sFractionalDigitsPattern;
	var bFR = false;
	if(LANGUAGE.value.toLowerCase() == FRENCH.toLowerCase())
	{
//		sFormat = sDigitsPattern + "." + sFractionalDigitsPattern + " ou " + sDigitsPattern + "," + sFractionalDigitsPattern; 
		bFR = true;
	}

	if (nFractionalLength == 0)
	{
		var sMsgCode = "M00033";	// default is float
		if (bPosOnly)
			sMsgCode = "M00047";	// default for positive float
	}
	else
	{
		var sMsgCode = "M00042";	// default is float
		if (bPosOnly)
			sMsgCode = "M00046";	// default for positive float
	}

	if (sFloatType)	
	{
		switch (sFloatType)
		{
			case "2":			// currency
				if (nFractionalLength == 0)
				{
					sMsgCode = "M00048";
					if (bPosOnly)
						sMsgCode = "M00049";	// positive only currency message				
				}
				else
				{
					sMsgCode = "M00027";
					if (bPosOnly)
						sMsgCode = "M00044";	// positive only currency message
				}
				break;
			case "3":			// percentage
				if (nFractionalLength == 0)
				{
					sMsgCode = "M00050";
					if (bPosOnly)
						sMsgCode = "M00051";	// positive only percentage message
				}
				else
				{
					sMsgCode = "M00040";
					if (bPosOnly)
						sMsgCode = "M00045";	// positive only percentage message		
				}
				break;
			case "4":			// negative parenthesis
				if (nFractionalLength == 0)
				{
					sMsgCode = "M00052";
				}
				else
				{
					sMsgCode = "M00041";
				}
				break;
		}
	}

	if(DEBUG) console.println("$$$ In validateKeystrokeFloat. sMsgCode: " + sMsgCode);		
	if (xfa.event.change != "")
	{
		if ( (bFR == false && xfa.event.change.match(/[-]|[0-9]|\./) == null)
	    	|| (bFR == true && xfa.event.change.match(/[-]|[0-9]|[,.]/) == null)
	    	|| (bPosOnly == true && xfa.event.change.match(/[-]/) != null)) 
	    {
	        xfa.event.change = "";
	        var sMsg = CoreMessages.getMessage(sMsgCode, nLength, nFractionalLength);

	        xfa.host.messageBox(sMsg, CoreMessages.getTitle(sMsgCode),1,0);
	    }
	 	else if(xfa.event.change.length == 1)
	 	{
			if(!CoreFunctions.floatKeystroke(bPosOnly, nLength, nFractionalLength))
			{
				// Removing this message to quiet down the keystroke validation			
				//xfa.host.messageBox(CoreMessages.getMessage("M00020", nLength), CoreMessages.getTitle("M00020"),1,0);
			}
		}
		else if(xfa.event.change.length > 1)		
		{
			if(!CoreFunctions.floatKeystroke(bPosOnly, nLength, nFractionalLength))
			{		
				xfa.host.messageBox(CoreMessages.getMessage(sMsgCode, nLength, nFractionalLength), CoreMessages.getTitle(sMsgCode),1,0);
			}
		}	
	}
	else	// no keystroke so we check for a max size on the xfa object itself
	{
		// When xfa.event.change is empty it's either a delete, backspace or field has reached it's max.
		// We only care about the field reaching it's max.  So we'll see if newText is greater than prevText
		if (xfa.event.newText.length >= xfa.event.prevText.length)
		{	
			// Removing this message to quiet down the keystroke validation	
			//xfa.host.messageBox(CoreMessages.getMessage("M00020", nLength), CoreMessages.getTitle("M00020"),1,0);
		}
		else
		{
			if(!CoreFunctions.floatKeystroke(bPosOnly, nLength, nFractionalLength))
			{
				// Removing this message to quiet down the keystroke validation			
				//xfa.host.messageBox(CoreMessages.getMessage("M00020", nLength), CoreMessages.getTitle("M00020"),1,0);
			}
		}

	}

}


