/**
 @function
 validateKeystrokeBN(oField, nCount, sTitle)

 @description
 Validate the current keystroke on a Business Number field.

 @param {Node} oField 	  - the portion of the business number field (9 digits or 4 digits).
 @param {Number} nCount   - one of 9 or 4 to indicate which part of the business number is validated.
 @param {String} sTitle   - the object titles name (ie. Account Number, ID Number, Partnership Number).    

 @example
 Examples:
 validateKeystrokeBN(this, CoreFunctions.BN_NINE);	- keystroke validation for the first 9 digits.

 Last Modified: 
 Sep 04, 2013  PDI000      Initial version
 Jul 08, 2014  PDI000      Handle 10 + 4 digit Identification Number.
 Dec 01, 2014  MXT187      Handle 9 digit Business Number.
 Jun 26, 2015  JXW170      Added the param sTitle to handle object titles provided by the form designer (ie. Account Number, ID Number, Partnership Number)
*/

function validateKeystrokeBN(oField, sType, sTitle)
{

	var nDigits = 9;	// default to 9 digits
	if (sType == NUM_BN_FOUR || sType == NUM_ID_FOUR)
	{
		nDigits = 4;
	}
	else if (sType == NUM_ID_TEN)
	{
		nDigits = 10;	
	}

	if (xfa.event.change != "")
	{
		if (!CoreFunctions.numericKeystroke(true, nDigits))
		{
			var sMsg = CoreMessages.getMessage("M00007");
			if (sType == NUM_BN_NINE)
			{
				sMsg = sMsg + "\n\n" + CoreMessages.getMessage("M00005");
			}
			else if (sType == NUM_BN_FOUR)
			{
				sMsg = sMsg + "\n\n" + CoreMessages.getMessage("M00006");
			}
			else if (sType == NUM_ID_NINE)
			{
				sMsg = sMsg + "\n\n" + CoreMessages.getMessage("M00054");
			}
			else if (sType == NUM_ID_FOUR)
			{
				sMsg = sMsg + "\n\n" + CoreMessages.getMessage("M00055");
			}
			else if (sType == NUM_ID_TEN)
			{
				sMsg = sMsg + "\n\n" + CoreMessages.getMessage("M00057");
			}
			else if (sType == NUM_BN_NINE_ONLY)
			{
				sMsg = sMsg + "\n\n" + CoreMessages.getMessage("M00059");
			}
			else if (sType == NUM_ACT_NINE)
			{
				sMsg = sMsg + "\n\n" + CoreMessages.getMessage("M00061", "9",sTitle);
			}
			else if (sType == NUM_ACT_FOUR)
			{
				sMsg = sMsg + "\n\n" + CoreMessages.getMessage("M00062", "4",sTitle);
			}

        	xfa.host.messageBox(sMsg, CoreMessages.getTitle("M00007"),1,0);
		}
	}
}


/**
 @function
 validateNumeric(oField, nCount, sCode, sTitle)

 @description
 Validate a numeric value. Value must contain only digits and be of the length specified. If validation
 fails the error message is determined by the sCode passed in.

 @param {String} sValue	  - the portion of the business number field (9 digits or 4 digits).
 @param {Number} nCount   - the number of digits expected in the value to be validated.
 @param {String} sCode    - one of a series of constants that indicate the type of field being validated.
                            For example, NUM_BN_NINE, NUM_SIN, etc.
 @param {String} sTitle   - the object titles name (ie. Account Number, ID Number, Partnership Number).                   

 @example
 Examples:
 validateNumeric(this, 9, CoreFunctions.NUM_BN_NINE);	- validate the first 9 digits of the Business Number.
 validateNumeric(this, 4, CoreFunctions.NUM_BN_FOUR);	- validation the second 4 digits of Business Number.

 Last Modified: 
 Sep 05, 2013  PDI000      Initial version
 Jul 11, 2014  PDI000      Added additional types for Identification Numbers
 Dec 01, 2014  MXT187      Handle 9 digit Business Number.
 Jun 26, 2015  JXW170      Added the param sTitle to handle object titles provided by the form designer (ie. Account Number, ID Number, Partnership Number)

*/
function validateNumeric(sValue, nCount, sCode, sTitle)
{
	if(!sValue)
		return true;

	if(DEBUG) console.println(">>>>>>> in validateNumeric, sValue is " + sValue);

	var regExpStr = "[0-9]{9}";				

	if (nCount)
	{
		regExpStr = "[0-9]{" + nCount + "}";
	}

	var codeMatchNumber = new RegExp(regExpStr);

	if(!sValue.match(codeMatchNumber) || sValue.length > nCount)
	{
		if(sCode == NUM_BN_NINE)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00005"),CoreMessages.getTitle("M00005"),1,0);
			return false;
		}
		else if (sCode == NUM_BN_FOUR)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00006"),CoreMessages.getTitle("M00006"),1,0);
			return false;
		}
		else if (sCode == NUM_SIN)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00026"),CoreMessages.getTitle("M00026"),1,0);
			return false;
		}
		else if(sCode == NUM_ID_NINE)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00054"),CoreMessages.getTitle("M00054"),1,0);
			return false;
		}
		else if (sCode == NUM_ID_FOUR)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00055"),CoreMessages.getTitle("M00055"),1,0);
			return false;
		}
		else if(sCode == NUM_ID_TEN)	// First 10 digits of Identification Number
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00057"),CoreMessages.getTitle("M00057"),1,0);
			return false;
		}
		else if(sCode == NUM_BN_NINE_ONLY)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00059"),CoreMessages.getTitle("M00059"),1,0);
			return false;
		}
		else if (sCode == NUM_ACT_NINE)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00061","9",sTitle),CoreMessages.getTitle("M00061"),1,0);
			return false;
		}
		else if (sCode == NUM_ACT_FOUR)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00062","4",sTitle),CoreMessages.getTitle("M00062"),1,0);
			return false;
		}	
	}

	return true;
}

