/**
 @function
 validateKeystrokeBNContiguous(oField)

 @description
 Validate the current keystroke on the a date field.

 @param {Node} oField 	- the SIN field.

 @example
 Examples:
 validateKeystrokeSIN(this);      - default settings.

 Last Modified: 
 Oct 04, 2012	PDI000      Initial version
 Aug 27, 2013   PDI000      Improve interaction to allow backspaces and deleting characters
*/
function validateKeystrokeBNContiguous(oField)
{
	var sFull = xfa.event.fullText;
	var sChange = xfa.event.change; 

	if(DEBUG) console.println("----- sFull = " + sFull);
	if(DEBUG) console.println("----- sChange = " + sChange);
	var nLen = sFull.length;
	if(DEBUG) console.println("----- nLen = " + nLen);
	if(DEBUG) console.println("----- selStart, selEnd = " + xfa.event.selStart + ", " + xfa.event.selEnd);

	if (nLen > 15)
	{
		xfa.event.change = "";
	 	return false;
	}

	var nCharCount = xfa.event.selStart + sChange.length;

	var sRegExp = "\\d{1,9}[a-zA-Z]{2}\\d{1,4}";

	switch (nCharCount)
	{
		case 0:
			sRegExp = "";
			break;
		case 1:
		case 2:
		case 3:
		case 4:
		case 5:
		case 6:
		case 7:
		case 8:
		case 9:
			sRegExp = "\\d{1,9}";
			break;
		case 10:
			sRegExp = "\\d{1,9}[a-zA-Z]{1}";
			break;
		case 11:
			sRegExp = "\\d{1,9}[a-zA-Z]{2}";
			break;
		case 12:
		case 13:
		case 14:
		case 15:
			sRegExp = "\\d{1,9}[a-zA-Z]{2}\\d{1,4}";
			break;
		}

	var oRegEx = new RegExp(sRegExp);	

	if(DEBUG) console.println("----- regEx = " + oRegEx );
	if(DEBUG) console.println("----- match = " + sFull.match(oRegEx));

	var sMatch = sFull.substring(0, nCharCount);
	if(DEBUG) console.println("----- sMatch = " + sMatch );

	//if (sFull != sFull.match(oRegEx))

	if (sMatch != sMatch.match(oRegEx))
	{
		xfa.event.change = "";
		xfa.host.messageBox(CoreMessages.getMessage("M00038"), CoreMessages.getTitle("M00038"),1,0);
		return false;
	}
	return true;
}


/**
 @function
 validateDate(dateIn, sFormat)

 @description
 Validates the passed in date string to the format YYYYMMDD.

 @param {String} dateIn - A string containing the date to be validated.
 @param {String} sFormat - A string containing the format of the date to 
                           be validated. Used for validation messages.

 @returns {Boolean} - true or false.  The result of the validation.

 @example
 Example:
 var bRes = CoreFunctions.validateDate(sDateField);						

 Last Modified: 
 Apr 18, 2011   PDI000      Replace hard-coded messages with use of calls to 
                            CoreMessages.getMessage().
 May 09, 2011   PDI000      Change the regular expression to match YYYYMMDD or
                            YYYY-MM-DD.  This will allow a formattEDD001ate to be pasted.
 Nov 07, 2011   PDI000      Check for month and day values less than 1.
                            Use the title from CoreMessages for the error messages.
 Feb 14, 2012   PDI000      Reject years less than 1900 to be consistent with XFA's epoch.
 Mar 28, 2012   PDI000      Reject days less than 1 for February.
 May 11, 2012   PDI000      Added format parameter.  Append format message to error messages.

*/

function validateDate(dateIn, sFormat)
{

	if(DEBUG) console.println("****** In validateDate, for " + xfa.event.name + ", rawValue = " + dateIn);
	//if(!dateIn.match(/[0-9]{4}\-{0,1}[0-9]{2}\-{0,1}[0-9]{2}/))
	if(!dateIn.match(/[0-9]{4}\-[0-9]{2}\-[0-9]{2}|[0-9]{8}/))
	{
		xfa.host.messageBox(CoreMessages.getMessage("M00002"),CoreMessages.getTitle("M00002"),1,0);
		return false;
	}

	var sMsg = "";
	if (sFormat)
	{
		sMsg = getDateValidationString(sFormat);
	}

	var sDate = dateIn;
	var sMonth;
	var sDay;
	if(dateIn.length == 8)
	{
		sMonth = sDate.substring(4,6);
		sDay = sDate.substring(6,8);
	}
	else
	{
		sMonth = sDate.substring(5,7);
		sDay = sDate.substring(8,10);
	}

	if(sMonth>12 || sMonth<1)
	{
		var sErrMsg = CoreMessages.getMessage("M00013");
		if (sMsg != "")
		{
			sErrMsg = sErrMsg + "\n\n" + sMsg;
		}
		xfa.host.messageBox(sErrMsg ,CoreMessages.getTitle("M00013"),1,0);
		return false;
	}

	if((sMonth==01)|(sMonth==03)|(sMonth==05)|(sMonth==07)|(sMonth==08)|(sMonth==10)|(sMonth==12)&&(sDay>31 || sDay<1))
	{
		var sErrMsg = CoreMessages.getMessage("M00014");
		if (sMsg != "")
		{
			sErrMsg = sErrMsg + "\n\n" + sMsg;
		}
		xfa.host.messageBox(sErrMsg, CoreMessages.getTitle("M00014"),1,0);
		return false;
	}

	if((sMonth==04)|(sMonth==06)|(sMonth==09)|(sMonth==11)&&(sDay>30 || sDay<1))
	{
		var sErrMsg = CoreMessages.getMessage("M00015");
		if (sMsg != "")
		{
			sErrMsg = sErrMsg + "\n\n" + sMsg;
		}
		xfa.host.messageBox(sErrMsg, CoreMessages.getTitle("M00015"),1,0);
		return false;
	}

	var sYear = sDate.substring(0,4);
	if(sYear < 1900)
	{
		var sErrMsg = CoreMessages.getMessage("M00024", "1900");
		if (sMsg != "")
		{
			sErrMsg = sErrMsg + "\n\n" + sMsg;
		}
		xfa.host.messageBox(sErrMsg, CoreMessages.getTitle("M00024"),1,0);
		return false;
	}

	if (sMonth == 2) 
	{ 			
		// Leap year checking
		var isLeap = (sYear % 4 == 0 && (sYear % 100 != 0 || sYear % 400 == 0));
		if (sDay > 29 || (sDay==29 && !isLeap) || sDay < 1) 
		{
			var sMaxDays = "28";
			if (isLeap)
				sMaxDays = "29";

			var sErrMsg = CoreMessages.getMessage("M00028", sMaxDays);
			if (sMsg != "")
			{
				sErrMsg = sErrMsg + "\n\n" + sMsg;
			}
			//xfa.host.messageBox(CoreMessages.getMessage("M00016", sYear, sDay), CoreMessages.getTitle("M00016"));
			xfa.host.messageBox(sErrMsg, CoreMessages.getTitle("M00028"),1,0);
			return false;
		}
	}

	return true;
}

/**
 @function
 validateEmail(email)

@description
 Validates the passed in Email address string.

 @param {String} email - A string containing the Email address to be validated.

 @returns {Boolean} - true or false.  The result of the validation.

 @example
 Example:
 var bRes = CoreFunctions.validateEmail(sEmail);						

 Last Modified: 
 Dec 11, 2014	PDI000      Created.
 Jan 25, 2016   PDI000      Accept apostrophes before the ampersand

*/
function validateEmail(emailIn)
{
	if(!emailIn)
		return true;

	if(DEBUG) console.println(">>>>>>> in validateEmail, emailIn is " + emailIn);

	if(!emailIn.match(/^[0-9a-zA-Z]*([0-9a-zA-Z]*[-._+'])*[0-9a-zA-Z]+@[0-9a-zA-Z]+([-.][0-9a-zA-Z]*)*$/))
	{
		xfa.host.messageBox(CoreMessages.getMessage("M00060"),CoreMessages.getTitle("M00060"),1,0);
		return false;
	}
	else if(emailIn.length > 75)
	{
		xfa.host.messageBox(CoreMessages.getMessage("M00011", "75"),CoreMessages.getTitle("M00011"),1,0);
		return false;
	}

	return true;
}

/**
 @function
 validateMonthDay(dateIn, [sYear])

 @description
 Validates the passed in string to the format MMDD.

 @param {String} dateIn	 - A string containing the Month/Day to be validated in the format MMDD.
 @param {String} sYear   - (optional) the year that the Month/Day will be validated against.  The default
                         is the current year.
 @param {String} sFormat - (optional) If provided (MMDD) the format is passed on to validateDate.

 @returns {Boolean}      - The result of the validation.

 @example
 Example:
 var bRes = CoreFunctions.validateMonthDay(sMonthDayField);						
 var bRes = CoreFunctions.validateMonthDay(sMonthDayField, "2009");

 Last Modified: 
 Aug 15, 2011   PDI000      Created.
 Feb 02, 2012   PDI000      If the year is not known the processing for February will
                            only check for a day in the range of 1-29.
 May 11, 2012   PDI000      The date format MMDD.
*/
function validateMonthDay(dateIn, sYear, sFormat)
{

	if(DEBUG) console.println("****** In validateMonthDay, for " + xfa.event.name + ", rawValue = " + dateIn);
	//if(!dateIn.match(/[0-9]{4}\-{0,1}[0-9]{2}\-{0,1}[0-9]{2}/))
	if(!dateIn.match(/[0-9]{2}\-[0-9]{2}|[0-9]{4}/))
	{
		xfa.host.messageBox(CoreMessages.getMessage("M00019"),"Invalid Date",1,0);
		return false;
	}

	if (!sYear)	
	{
		// Don't default to the current year for February.  Just check for a day in the range of 1-29.
		var sMonth = dateIn.substring(0,2);
		var sDay = dateIn.substring(2,4);
		if(DEBUG) console.println("****** In validateMonthDay (no Year), month is " + sMonth + ", day is " + sDay);
		if(sMonth==02 &&(sDay>29 || sDay<1))
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00025"), CoreMessages.getTitle("M00025"),1,0);
			return false;
		}
		else
		{
			var sToday = new Date();
			sYear = sToday.getFullYear();
		}
	}

	var sFullDate = sYear + dateIn;

	return validateDate(sFullDate, sFormat);

}

/**
 @function
 validateYearMonth(dateIn, sFormat)

 @description
 Validates the passed in string to the format YYYYMM or YYMM.

 @param {String} dateIn - A string containing the Year/Month to be validated in the format YYYYMM.
 @param {String} sFormat - A string containing the format YYYYMM (default) or YYMM.

 @returns {Boolean} The result of the validation.

 @example
 Last Modified: 
 Nov 07, 2011   PDI000      Created.
 Apr 24, 2012   PDI000      Added 'sFormat' parameter to allow for YYMM format.

 */
function validateYearMonth(dateIn, sFormat)
{

	if(DEBUG) console.println("****** In validateYearMonth, dateIn = " + dateIn + ", sFormat = " + sFormat);

	if(sFormat == CoreFunctions.YYMM)
	{
		if(dateIn.length != 4 || !dateIn.match(/[0-9]{4}/))
		{
			showDateValidation (sFormat);
			return false;
		}	
	}
	else	// default to YYYYMM format
	{
		if(dateIn.length != 6 || !dateIn.match(/[0-9]{4}\-[0-9]{2}|[0-9]{6}/))
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00022"),CoreMessages.getTitle("M00022"),1,0);
			return false;
		}
	}

	var sFullDate;

	if(sFormat == CoreFunctions.YYMM)
	{
		sFullDate = "20" + dateIn + "01";
	}
	else
	{
		sFullDate = dateIn + "01";
	}

	return validateDate(sFullDate, sFormat);	
}


/**
 @function
 validateYear(dateIn, sFormat)

 @description
 Validates the passed in string to the format YYYY.

 @param {String} dateIn - A string containing the Year/Month to be validated in the format YYYYMM.

 @returns {Boolean} The result of the validation.

 @example
 Last Modified: 
 Jun 06, 2012   PDI000      Created.

 */
function validateYear(dateIn, sFormat)
{
	if(DEBUG) console.println("****** In validateYear, dateIn = " + dateIn + ", sFormat = " + sFormat);

	var retCode = true;

    if(!dateIn.match(/[0-9]{4}/) || (dateIn * 1) < 1900)
	{
		var sMsg1 = CoreMessages.getMessage("M00024", "1900");
		var sMsg2 = CoreMessages.getMessage("M00032", "4");

		xfa.host.messageBox(sMsg1 + "\n\n" + sMsg2, CoreMessages.getTitle("M00024"),1,0);
		retCode = false;
	}
	else if(dateIn.length > 4)
	{
		xfa.host.messageBox(CoreMessages.getMessage("M00032", "4"), CoreMessages.getTitle("M00032"),1,0);
		retCode = false;
	}

	return retCode;
}



/**
 @function
 validatePostalCode(pcIn)

 @description
 Validates the passed in post code string to the format A1A1A1.

 @param {Number} pcIn - A string containing the postal code to be validated.

 @returns {Boolean} The result of the validation.

 @example
 Example:
 var bRes = CoreFunctions.validatePostalCode(PartA_PostalCode.rawValue);						

 Last Modified: 
 Jul 08, 2011	PDI000	    Replace hard-coded message with core message.

*/
function validatePostalCode(pcIn)
{

	if (!pcIn)
		return true;

	// console.println(">>>>>>> pcIn is " + pcIn);
	if(!pcIn.match(/[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\d[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\s{0,1}\d[AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz]\d$/))
	{
		xfa.host.messageBox(CoreMessages.getMessage("M00001"),CoreMessages.getTitle("M00001"),1,0);
		return false;
	}

	return true;
}

/**
 @function
 validateZipCode(zipIn)

 @description
 Validates the passed in Zip Code string to either 5 or 9 digits.

 @param {Number} zipIn - A string containing the Zip Code to be validated.

 @returns {Boolean} The result of the validation.

 @example
 Example:
 var sZipCode = PartA_ZipCode.rawValue;
 var bRes = CoreFunctions.validateZipCode(sZipCode);						

 Last Modified: 
 Sep 17, 2012	PDI000	    Initial version.

*/
function validateZipCode(zipIn)
{

	if (!zipIn)
		return true;

	// console.println(">>>>>>> zipIn is " + zipIn);
	//if (!zipIn.match(/d{5}/) || (zipIn.length > 5 && zipIn.length < 9))
	if (!zipIn.match(/[0-9]{5}/) || (zipIn.length > 5 && zipIn.length < 9) || zipIn.length > 9)	
	{
		xfa.host.messageBox(CoreMessages.getMessage("M00035"),CoreMessages.getTitle("M00025"),1,0);
		return false;
	}

	return true;
