/**
 @function
 validatePhoneNumber(pnIn, sType)

 @description
 Validates the passed in phone number string to 10 numeric digits.

 @param {Number} pnIn - A string containing the phone number to be validated.
 @param {String} sType - A string containing type of the phone number to be validated.
                         The available types are "STANDARD" - default, 10-digit North American number.
                                                 "AREACODE" - the 3 digit area code.
                                                 "PHONENUMBER - the 7 digit phone number.

 @returns {Boolean} The result of the validation.

 @example
 Example:
 var bRes = CoreFunctions.validatePhoneNumber(sPhoneNum);
     - validates a 10 digit number

 var bRes - CoreFunctions.validatePhoneNumber(sAreaCode, CoreFunctions.PHONE_AREACODE);
     - validates a 3 digit Area Code						

 Last Modified: 
 Jul 08, 2011	PDI000      Replace hard-coded message with core message.
 Aug 28, 2012	PDI000		Check the phone number length.		
 Sep 27, 2012   PDI000      Allow for validating Split Phone Numbers
 Apr 25, 2014	PDI000 		Accept a parameter for fax number for messaging. 

*/
function validatePhoneNumber(pnIn, sType)
{
	if(!pnIn)
		return true;

	var bRet = true;

	if (sType == PHONE_AREACODE)
	{
		if(!pnIn.match(/[0-9]{3}/) || pnIn.length > 3)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00036"),CoreMessages.getTitle("M00036"),1,0);
			bRet = false;
		}
	}
	else if (sType == PHONE_NUMBER)
	{
		if(!pnIn.match(/[0-9]{7}/) || pnIn.length > 7)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00037"),CoreMessages.getTitle("M00037"),1,0);
			bRet = false;
		}
	}
	else if (sType == PHONE_FAX)
	{
		// console.println(">>>>>>> pnIn is " + pnIn);
		if(!pnIn.match(/[0-9]{10}/) || pnIn.length > 10)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00053"),CoreMessages.getTitle("M00053"),1,0);
			bRet = false;
		}
	}
	else
	{
		// console.println(">>>>>>> pnIn is " + pnIn);
		if(!pnIn.match(/[0-9]{10}/) || pnIn.length > 10)
		{
			xfa.host.messageBox(CoreMessages.getMessage("M00012"),CoreMessages.getTitle("M00012"),1,0);
			bRet = false;
		}
	}

	return bRet;
}

