/**
 @function
 isHidden(oField)

 @description
 Recursively bubbles up to see if any parents are hidden<br> 
 because if a parent is hidden all the children are effectively hidden.

 @param {Node} oField - the field whose presence we are checking.

 @returns {Boolean}  true if the field is hidden.

 @example
 Examples:
 if (isHidden(PartA_Name))
     console.println("Name is hidden.");	 

 Last Modified: 
 Jun 09, 2011   PDI000      Initial version
 Feb 06, 2012   PDI000      Use try/catch to protect from script failure when dealing
                            with a field that doesn't have a presence property.  This
                            changed when we moved to 9 and greater as our target version.
 Mar 12, 2013   PDI000      Skip over "area" nodes when bubbling up the ancestry.
*/
function isHidden(oField)
{
	if (oField)
	{
		//if (oField.className != "form" && oField.className != "area" )
		if (oField.className != "form" )
		{
			try
			{
				if (oField.className == "area")
				{
					if(isHidden(oField.parent))
							return true;
				}
				else
				{
					if (oField.presence == "hidden")
					{
						return true;
					}
					else
					{
						if(isHidden(oField.parent))
							return true;
					}
				}
			}
			catch(err)
			{
				if(true) console.println("\n <> CAUGHT " + err.message + " for " + oField.name + ", " + oField.className + "\n");
				return false;
			}
		}
	}
	return false;
}

/**
 @function
 isReadOnly(oField)

 @description
 Returns true if the field is ReadOnly or Protected.  Recursively bubbles up to see if any parents<br> 
 are ReadOnly or Protected.

 @param {Node} oField - the field whose access we are checking.

 @returns {boolean} true if the field is ReadOnly or Protected.

 @example
 Examples:
 if (isReadOnly(PartA_Name))
    console.println("Name is readOnly.");	 

 Last Modified: 
 Jul 18, 2011   PDI000      Initial version
 Feb 06, 2012   PDI000      Use try/catch to protect from script failure when dealing
                            with a field that doesn't have an access property.  This
                            changed when we moved to 9 as our target version.
 Mar 12, 2013   PDI000      Skip over "area" nodes when bubbling up the ancestry.

*/
function isReadOnly(oField)
{
	if (oField)
	{
		//if (oField.className != "form" && oField.className != "area")
		if (oField.className != "form")
		{
			try
			{
				if (oField.className == "area")
				{
					if(isReadOnly(oField.parent))
						return true;
				}
				else
				{
					if (oField.access == "readOnly" || oField.access == "protected")
					{
						return true;
					}
					else
					{
						if(isReadOnly(oField.parent))
							return true;
					}
				}
			}
			catch(err)
			{
				if(true) console.println("\n <> CAUGHT " + err.message + " for " + oField.name + ", " + oField.className + "\n");
				return false;
			}
		}
	}
	return false;
}

/**
 @function
 setFillColour(oField, sAction, sColour)

 @description
 Sets the fill colour of the field to either of the predefined colours for Exit or Enter.<br>
 The optional parameter sColour can be used to specify an alternative fill colour.

 @param {Node} oField - the field whose fill colour we are setting.
 @param {String} sAction - the action on which the colour is based.  This should be one of the availbale
                           constants ENTER or EXIT
 @param {String} sColour - (optional) the fill colour in an RGB string (ex.  "255,170,170")

 @example
 Examples:
 setFillColour (this, CoreFunctions.ENTER);
 setFillColour (this, CoreFunctions.EXIT, "145,145,145");

 Last Modified: 
 Jun 09, 2011   PDI000      Initial version
 Feb 08, 2011   PDI000      Add the optional parameter sColour to allow the caller to 
                            specify the fill colour.
                            Use the fill colour of the ui object so only the widget, not
                            the entire object, gets coloured.

 Apr 26, 2012   PDI000      Detect dynamic/static state of host form. Add processing for 
                            static form.

*/
function setFillColour(oField, sAction, sColour)
{	
	if(DEBUG) console.println("In setFillColour for " + oField.name);

	var sRGB = "255,255,255";

	// Is this a dynamic form?
	if(event.target.dynamicXFAForm)
	{		
		if (sAction == ENTER)
			sRGB = "255,255,170";

		if (sColour)
			sRGB = sColour;

		if (oField.className == "exclGroup")
		{
			// Look for child fields.
			for (var i = 0; i < oField.nodes.length; i++)
			{
				var oChildNode = oField.nodes.item(i);
				setFillColour(oChildNode, sAction, sColour);
			}
		}
		else if (oField.className == "field")
		{
			if(DEBUG) console.println("--- In setFillColour for " + oField.name);

			if (oField.ui.oneOfChild.border.presence == "hidden")
			{
				oField.ui.oneOfChild.border.presence = "visible";
				oField.ui.oneOfChild.border.edge.presence = "hidden";	
			}		

			oField.ui.oneOfChild.border.fill.color.value = sRGB;
		}
	}
	else // handle the fill colour for a static form
	{
		//sample SOM expression: xfa[0].form[0].CRA_Template_EN[0].Monroe[0].Field1[0]
		var sSOM = oField.somExpression;	
		var sShortSOM = sSOM.substring(15);	// trim the "xfa[0].form[0]" off of the SOM expr
		if(DEBUG) console.println("In setFillColour, som is " + sSOM + ", short SOM is " + sShortSOM);	

		var f = event.target.getField(sShortSOM);

		sRGB = ["RGB",1,1,0.694];	// light yellow

		if (sAction == EXIT)
		{
			sRGB = color.transparent;
		}

		if (sColour)
		{
			// parse the colour string for the R, G and B values.
			var firstIdx = sColour.indexOf(",", 0);
			var sR = sColour.substring(0, firstIdx);
			var secondIdx = sColour.indexOf(",", firstIdx + 1);
			var sG = sColour.substring(firstIdx + 1, secondIdx);
			var sB = sColour.substring(secondIdx + 1);
			if(DEBUG) console.println("In setFillColour sR sG sB = " + sR + " " + sG + " " + sB);

			// the 0-255 based RGB values have to be converted to the 0-1 based values that Acroforms uses.
			var nR = roundNumber(sR/255, 3);
			var nG = roundNumber(sG/255, 3);
			var nB = roundNumber(sB/255, 3);
			// create the colour array
			sRGB = ["RGB", nR, nG, nB]; 
		}

		if(DEBUG) console.println("In setFillColour, Static sRGB is " + sRGB);	

		f.fillColor = sRGB;	
		//f.fillColor = color.transparent;

	}	
}


/**
 @function
 incrementSubformSRT(oNode, sNewInstanceNum, sInitialInstanceNum)

 @description  
 This function should be used as the initial call in most cases where the "Instance" or "Le cas" number in the<br>
 Screen Reader Text needs to be incremented as subforms are addEDD001ynamically.  For English forms<br>
 "Instance" is used.  For French forms "Le cas" is used.

 For example, the SRT for a field in a dynamic subform might be "Funds held at year end. Instance 1.". In the<br>
 "Initialize" javascript the following code would be added:

 var nInstCount = this.parent.index + 1;
 CoreFunctions.incrementSubformSRT(this, nInstCount, "1");

 In this way, when a new subform is instantiated the field's initialize code will fire and a call is made to<br>
 incrementSubformSRT. The new instance number is pulled from the field's parent subform and passed to<br>
 the function.  

 @param {Node} oNode - The root node of the subform.
 @param {String} sNewInstanceNum - The new instance number of the subform to replace the initial instance number.
 @param {String} sInitialInstanceNum - The initial instance number of the subform that will be replaced.

 @example
 Examples:
 var nInstCount = this.parent.index + 1;
 CoreFunctions.incrementSubformSRT(this, nInstCount, "1");       // Replaces "Instance 1" with
                                                                 // "Instance x" where x is the
                                                                 // variable nInstCount.
 Last Modified: 
 Aug 28, 2013   PDI000      Initial version

*/
function incrementSubformSRT(oNode, sNewInstanceNum, sInitialInstanceNum)
{
	var sInstString = "Instance"; // default to Instance.

	// Check for Language
	if (LANGUAGE.value.toLowerCase() == ENGLISH.toLowerCase())	
	{
		sInstString = "Instance";
	}
	else if (LANGUAGE.value.toLowerCase() == FRENCH.toLowerCase())
	{
		sInstString = "Le cas";
	}
	else
	{
		console.println("The LANGUAGE Form Variable value " + LANGUAGE.value + " is not recognized.");
	}

	var sNewInst = sInstString + " " + sNewInstanceNum + ".";
	var sOldInst = sInstString + " " + sInitialInstanceNum + ".";
	enhanceSubformSpeakText(oNode, sNewInst, sOldInst);
}

