/**
 @function
 enhanceSubformSpeakText(oNode, sText, [sReplace])

 @description  
 This function uses oNode as a starting point and recursively walks through all child fields.<br>
 For each field append sText to the speak text.

 @param {Node} oNode - The root node from which the recursive walk will begin.
 @param {String} sText - The text string to be added to the fields.
 @param {String} sReplace - (optional) A string to search for and replace in the existing speak text with sText. 

 @example
 Examples:
 var nCount = enhanceSubformSpeakText(PartA_Sub, "Instance 2" ); //Appends "Instance 2" to the speak 
                                                                 //text of all fields beneath the
                                                                 //PartA_Sub object.

 var oInst = form1.Page1.Person_sub._Person.addInstance(true);
 var nInstCount = oInst.index + 1;                                                                
 CoreFunctions.enhanceSubformSpeakText(oInst, "Instance " + nInstCount, "Instance 1");
                                                                 // Replaces "Instance 1" with
                                                                 // "Instance x" where x is the
                                                                 // variable nInstCount.

 Last Modified: 
 Jun 21, 2011   PDI000      Initial version
 Apr 09, 2013   PDI000      Add the optional sReplace parameter 

*/
function enhanceSubformSpeakText(oNode, sText, sReplace)
{

	if (oNode.className == "exclGroup" || oNode.className == "subform"  || oNode.className == "subformSet" || oNode.className == "area")
	{
		// Look for child fields.

		for (var i = 0; i < oNode.nodes.length; i++)
		{
			var oChildNode = oNode.nodes.item(i);
			if(enhanceSubformSpeakText(oChildNode, sText, sReplace))
				return;
		}
	}
	else if (oNode.className == "field")
	{
		switch (oNode.ui.oneOfChild.className)
		{
			case "button":				
			case "checkButton":			
			case "choiceList":	
			case "dateTimeEdit":
			case "imageEdit":
			case "numericEdit":			
			case "passwordEdit":			
			case "textEdit":			
			case "signature":
			case "barcode":
				addSpeakText(oNode, sText, sReplace)
				break;

			default:
				// unknown field type
				break;
		}
	}
}

/**
 @function
 addSpeakText(oField, sText, sReplace)

 @description
 Appends text to a field's existing speak text.

 @param {Node} oField - the field whose fill colour we are setting.
 @param {String} sText - the text to append
 @param {String} sReplace - (optional) A string to search for and replace in the existing speak text with sText.

 @example
 Examples:
 addSpeakText (this, "Instance 2");      // Appends "Instance 2" to the SRT.                      

 addSpeakText (this, "Instance 2", "Instance 1");        // replace "Instance 1" with "Instance 2" in the SRT.

 Last Modified: 
 Jun 21, 2011	PDI000      Initial version
 Apr 09, 2013   PDI000      Add the optional sReplace parameter 

*/		
function addSpeakText(oField, sText, sReplace)
{
	if (DEBUG) console.println("***** In addSpeakText... oField is " + oField.name + " sText is " + sText + ", sReplace is " + sReplace);

	var oStaticField;

	var sSpeak = getSpeakText(oField);

	if (typeof sReplace != "undefined")
	{
		// Look for the Replace string in the speak text
		var startIdx = sSpeak.indexOf(sReplace, 0);
		if (startIdx != -1)
		{
			// Add the new text in place of the Replace text 
			var sNew = sSpeak.substring(0, startIdx) + sText + sSpeak.substring(startIdx + sReplace.length);
			setSpeakText(oField, sNew);
		}
	}
	else
	{
		// This function is used mostly for adding or replacing strings like
		// "(Required)" or "Instance 2". Since they should only occur once in the SRT
		// we'll check to make sure they're not already in the string.  If the string
		// is found we won't add it.
		var sTextIdx = sSpeak.indexOf(sText, 0);
		if (sTextIdx == -1) // not found
		{
			setSpeakText(oField, sSpeak + sText);
		}
	}	
}

/**
 @function
 setSpeakText(oField, sText)

 @description
 Sets a field's speak text.

 @param {Node} oField - the field whose speak text we are setting.
 @param {String} sText - the string that will be used for the field's speak text. 

 @example
 Examples:
 var sSpeak = setSpeakText(oField);

 Last Modified: 
 Aug 28, 2012	PDI000      Initial version replacement
 Mar 31, 2014   PDI000      Use the Acrobat API to access all fields except radio buttons

*/
function setSpeakText(oField, sText)
{
	if (DEBUG) console.println("@@@ In setSpeakText... oField is " + oField.name + " sText is " + sText);

	try
	{	
		if(event.target.dynamicXFAForm)
		{
			oField.assist.speak.value = sText;
		}
		else // form is static
		{

			if (oField.ui.oneOfChild.className == "checkButton" && oField.parent.className == "exclGroup")
			{
				oField.assist.speak.value = sText;	
			}
			else
			{
				//sample SOM expression: xfa[0].form[0].CRA_Template_EN[0].Monroe[0].Field1[0]
				var sSOM = oField.somExpression;	
				var sShortSOM = sSOM.substring(15);	// trim the "xfa[0].form[0]" off of the SOM expr
				if(DEBUG) console.println("@@@ In setSpeakText, som is " + sSOM + ", short SOM is " + sShortSOM);	

				var f = event.target.getField(sShortSOM);
				f.userName = sText;	
			}	

		}
	}
	catch (err)
	{
		console.println("Javascript Exception\n\n" + err + "\n\nThrown in setSpeakText...");
	}
}

/**
 @function
 getSpeakText(oField)

 @description
 Returns a field's existing speak text.

 @param {Node} oField - the field whose speak text we are getting.

 @returns {string} the field's speak text.

 @example
 Examples:
 var sSpeak = getSpeakText(oField);

 Last Modified: 
 Aug 28, 2012	PDI000      Initial version replacement
 Mar 31, 2014   PDI000      Use the Acrobat API to access all fields except radio buttons

*/
function getSpeakText(oField)
{
	var sSpeakText = oField.assist.speak.value;
	if(event.target.dynamicXFAForm)
	{	
		if (sSpeakText == "")
		{
			sSpeakText = oField.assist.toolTip.value;
		}
		if (sSpeakText == "")
		{
			if(oField.caption.value.resolveNode("#text") != null)
				sSpeakText= oField.caption.value.resolveNode("#text").value;
		}
		if (sSpeakText == "")
		{
			if(oField.caption.value.resolveNode("exData") != null)
				sSpeakText= oField.caption.value.resolveNode("exData").value;			
		}

		if (sSpeakText == "")
		{
			sSpeakText= oField.name;
		}
	}
	else
	{
		try
		{
			if (oField.ui.oneOfChild.className == "checkButton" && oField.parent.className == "exclGroup")
			{				
				sSpeakText = oField.assist.speak.value;
			}
			else
			{	
				var sSOM = oField.somExpression;	
				var sShortSOM = sSOM.substring(15);	// trim the "xfa[0].form[0]" off of the SOM expr
				var f = event.target.getField(sShortSOM);
				sSpeakText = f.userName;
			}
		}
		catch(err)
		{
			console.println("\n <> CAUGHT " + err.message + " for " + oField.name + ", " + oField.className + "\n");
			return false;
		}
	}

	return sSpeakText;
}

/**
 @function
 setRequiredSRT(oField, bRequired)

 @description
 This function starts the process for adding/removing a string to/from a field's Screen Reader Text that indicates
 that the field is required. For most fields the oField parameter should be the field's object node.  For radio 
 buttons use the group node.

 @param {Node} oField - the field whose speak text we are modifying.
 @param {Boolean} bRequired - indicates if a "Mandatory" string should be added or removed from the SRT.

 @returns {Boolean} - indicates success (true) or failure (false) of the operation.

 @example
 Examples:
 var bReturn = setRequiredSRT(oField, true); 

 Last Modified: 
 Mar 31, 2014	PDI000      Initial version

*/
function setRequiredSRT(oField, bRequired)
{
	if (DEBUG) console.println("~*~ In setRequired... oField is " + oField.name + " bRequired is " + bRequired);

	if (oField.className == "exclGroup")
	{
		// Look for child fields.
		var oChildNode;
		for (var i = 0; i < oField.nodes.length; i++)
		{
			oChildNode = oField.nodes.item(i);
			if (oChildNode.className == "field")
				setRequiredSRT(oChildNode, bRequired);
		}
	}
	else
	{		
		var sText = "";	

		// Check for Language
		if (LANGUAGE.value.toLowerCase() == ENGLISH.toLowerCase())	
		{
			if (oField.ui.oneOfChild.className == "checkButton")
			{
				sText = REQUIRED_GROUP_E;
			}
			else
			{
				sText = REQUIRED_FIELD_E;
			}
		}
		else if (LANGUAGE.value.toLowerCase() == FRENCH.toLowerCase())
		{
			if (oField.ui.oneOfChild.className == "checkButton")
			{
				sText = REQUIRED_GROUP_F;
			}
			else
			{
				sText = REQUIRED_FIELD_F;
			}
		}
		else
		{
			console.println("The LANGUAGE Form Variable value " + LANGUAGE.value + " is not recognized.");
			return false;
		}

		if (bRequired)
		{
			addSpeakText(oField, sText);	
		}
		else
		{
			addSpeakText(oField, "", sText);
		}

		return true;
	}
}

/**
 @function
 setRequired(oField, bRequired)

 @description
 This function starts the process for setting a field to required or not required.  This includes modifying the
 field's Screen Reader Text accordingly.

 @param {Node} oField - the field whose speak text we are modifying.
 @param {Boolean} bRequired - indicates if the field should be required or not.

 @returns {Boolean} - indicates success (true) or failure (false) of the operation.

 @example
 Examples:
 var bReturn = setRequired(oField, true); 

 Last Modified: 
 Apr 02, 2014	PDI000      Initial version

*/
function setRequired(oField, bRequired)
{
	if (DEBUG) console.println("~*~ In setRequired... oField is " + oField.name + " bRequired is " + bRequired);

	var bRet = true;

	// First handle setting the field's mandatory property
	if (bRequired)
		oField.mandatory = "error";
	else
		oField.mandatory = "disabled";

	// this extra step is needed for static forms 
	if (event.target.dynamicXFAForm == false)
	{
		var oAcro =	getAcroObject(oField);
		if (oAcro != null)		
			oAcro.required = bRequired;
	}	

	// Now handle the SRT
	setRequiredSRT(oField, bRequired)

}

