	{
		console.println("\n <> In getAcroObject... CAUGHT " + err.message + " for " + oField.name + ", " + oField.className + "\n");
	}

	return oAcro;
}

/**
 @function
 roundNumber(num, places)

 @description
 Rounds off the supplied numeric value to the supplied number of decimal places.
 Result will be padded with trailing zeros if needed. 
 Note: This function rounds up on values of 5.

 @param {Number} num         - The numeric value to be rounded.
 @param {Number} places      - The number of decimal places that num will be rounded to.
                               The default is 2.

 @returns {Number}           - the rounded number.

 @example
 Examples:
 roundNumber (123.333);      - Round the number to the default of 2 decimal places.
                             - Returns 123.33
 roundNumber (123.3, 2);     - Round the number to 2 decimal places.
                             - Returns 123.30
 roundNumber (3.456456, 4);  - Round the number to 4 decimal places.
                             - Returns 3.4565
*/
function roundNumber(num, places)
{

	if (!places)
		places = 2; 	// default is 2 places

	// The idea is to shift the decimal right by the number of decimal places required.  Round the value.  Then
	// shift the decimal left by the same number of decimal places.  However floating point arithmetic is problematic.
	// For instance 162.295 * 100 has a result of 16229.499999999998.  If you're really curious as to why this happens there's
	// a good article here: http://docs.sun.com/source/806-3568/ncg_goldberg.html.
	// As a work-around the algorithm below converts the number to a string and moves the decimal point in the 
	// string by the required number of places, rounds off the result and then moves the decimal point back by the 
	// required number of places. 

	var sNum = num.toString();
	var decPos = sNum.indexOf(".");
	if (decPos == -1)
	{
		sNum = sNum + ".";
		decPos = sNum.length - 1;
	}

	// Pad with trailing zeros if needed	
	var sub1 = sNum.substring(decPos + 1);
	var nPad = places - sub1.length;
	for (;nPad > 0; nPad--)
	{
		sNum = sNum + "0";
	}

	// Shift the decimal point right
	sNum = sNum.substr(0, decPos) + sNum.substr(decPos + 1, places) + "." + sNum.substr(decPos + 1 + places);

	// account for leading zeros
	var nZeroCount = 0;
	var i = 0;
	for (i = 0; i < sNum.length; i++)
	{
		if (sNum[i] == "0")
		{
			nZeroCount++;
		}
		else
		{
			break;
		}
	}

	// Round off	
	var nTmp = Math.round(sNum);

	// replace leading zeros
	sNum = nTmp.toString();
	for (i = 0; i < nZeroCount; i++)
	{
		sNum = "0" + sNum;
	}
	var len = sNum.length;

	// Shift the decimal point left
	sNum = sNum.substr(0, len - places) + "." + sNum.substr(len - places);

	return sNum;
}

/**
 @function
 setDisplay(oField, sMode)

 @description
 This function sets the display (or presence) of a field.  

 @param {String} oField - the field whose dsiplay mode will be set.
 @param {Object} sMode  - the display mode. "visible" or "hidden" or "invisible".	

 @example
 Examples:
 var oField = form1.Page1.Image1;
 CoreMessages.setDisplay(oField, Corefunctions.DISPLAY_HIDDEN);
 - sets the Image1 field to hidden.

 Last Modified: 
 Jun 13, 2012   PDI000      Initial version
 Feb 10, 2014   PDI000      Add "invisible" option for ease of use.
 Feb 10, 2014   PDI000      Show object SOM in 'catch' processing.

*/
function setDisplay(oField, sMode)
{
	if(sMode != DISPLAY_HIDDEN && sMode != DISPLAY_VISIBLE && sMode != DISPLAY_INVISIBLE)
	{
		console.println("Error in setDisplay... invalid mode:" + sMode);
		return;
	}

	try
	{	
		if(event.target.dynamicXFAForm)
		{
			oField.presence = sMode;		
		}
		else // form is static
		{
			//sample SOM expression: xfa[0].form[0].CRA_Template_EN[0].Monroe[0].Field1[0]
			var sSOM = oField.somExpression;	
			var sShortSOM = sSOM.substring(15);	// trim the "xfa[0].form[0]" off of the SOM expr
			if(DEBUG) console.println("In setDisplay, som is " + sSOM + ", short SOM is " + sShortSOM);	

			var f = event.target.getField(sShortSOM);
			if(sMode == DISPLAY_VISIBLE)
			{
				f.display = display.visible;	
			}
			else if (sMode == DISPLAY_HIDDEN)
			{
				f.display = display.hidden;
			}
			else if (sMode == DISPLAY_INVISIBLE)
			{
				f.display = display.hidden;		
			}
		}
	}
	catch (err)
	{
		console.println("Javascript Exception\n\n" + err + "\n\nThrown in setDisplay...");
		console.println("Object: " + oField.somExpression);
	}		
}


function isNumber(n)
{
	if(!isNaN(parseFloat(n)) && isFinite(n))
	{
		return true;
	}
	else
	{
		xfa.host.messageBox(CoreMessages.getMessage("M00007"),CoreMessages.getTitle("M00007"),1,0);
		return false;
	}
}

/**
 @function
 getLanguage()

 @description
 This function returns the either E for English (default) or F for French based on the LANGUAGE variable.  

 @example
 Examples:
 var sLang = CoreFunctions.getLanguage();

 Last Modified: 
 Sep 04, 2012   PDI000      Initial version

*/

function getLanguage()
{
	var retVal = "";

	try
	{
		if (LANGUAGE.value.toLowerCase() == ENGLISH.toLowerCase())	
		{
			retVal = CoreMessages.LANG_EN;
		}
		else if (LANGUAGE.value.toLowerCase() == FRENCH.toLowerCase())
		{
			retVal = CoreMessages.LANG_FR;
		}
		else
		{
			console.println("The LANGUAGE Form Variable value " + LANGUAGE.value + " is not recognized.");
			retVal = CoreMessages.LANG_EN;
		}
	}
	catch (err)
	{
		console.println(err + "\n\nPlease use LANGUAGE as the Form Variable name.");
	}

	return retVal;
}

/**
 @function
 getCountryOfProvState(sProvState)

 @description
 This function returns either "Canada" or "United States" depending on the Province
 or State passed in.  The processing is case-sensitive. 

 @param {String} sProvState - the Province or State. This may be the full string or 
 abbreviation.  For example it may be "Ontario" or "ON".

 @returns {String}           - the Country or an empty string if sProvState is not found.

 @example
 Examples:
 var sCountry = CoreFunctions.getCountryOfProvState(ProvState_DropDown.rawValue);
 - gets the Country of the ProvState dropdown.

 Last Modified: 
 Sep 07, 2012   PDI000      Initial version

*/
function getCountryOfProvState(sProvState)
{
	if (sProvState == null)
		return "";

	// The length of the parameter will tell us if it's an abbreviation.
	var nLen = sProvState.length;

	var sCountry = "";

	// Check for Language
	if (getLanguage() == CoreMessages.LANG_FR)
	{
		// process for French
		if (nLen == 2) // abbreviation
		{
			if (PROV_ABBR_ARRAY_F.indexOf(sProvState) != -1) // Canadian Provinces
			{
				sCountry = COUNTRY_CA_F;
			}
			else if (STATE_ABBR_ARRAY_F.indexOf(sProvState) != -1) // States
			{
				sCountry = COUNTRY_US_F;
			}
		}
		else
		{
			if (PROV_ARRAY_F.indexOf(sProvState) != -1) // Canadian Provinces
			{
				sCountry = COUNTRY_CA_F;
			}
			else if (STATE_ARRAY_F.indexOf(sProvState) != -1) // States
			{
				sCountry = COUNTRY_US_F;
			}
		}
	}	
	else
	{
		// process for English
		if (nLen == 2) // abbreviation
		{
			if (PROV_ABBR_ARRAY_E.indexOf(sProvState) != -1) // Canadian Provinces
			{
				sCountry = COUNTRY_CA_E;
			}
			else if (STATE_ABBR_ARRAY_E.indexOf(sProvState) != -1)
			{
				sCountry = COUNTRY_US_E;
			}
		}
		else
		{
			if (PROV_ARRAY_E.indexOf(sProvState) != -1) // Canadian Provinces
			{
				sCountry = COUNTRY_CA_E;
			}
			else if (STATE_ARRAY_E.indexOf(sProvState) != -1)
			{
				sCountry = COUNTRY_US_E;
			}
		}
	}

	return sCountry;
}


/**
 @function
 getAbbrOfCountry(sCountry)

 @description
 This function returns either "CA" (for Canada), "US" (for United States or États-Unis) or
 "" (for anything else).  The processing is case-sensitive.

 @param {String} sCountry - the Country. "Canada", "United States", "États-Unis", or other.

 @returns {String}           - the abbreviation ("CA" or "US") or an empty string.

 @example
 Examples:
 var sCountryAbbr = CoreFunctions.getAbbrOfCountry(PartA_Country.rawValue);
 - gets the abbreviation of the value of the PartA_Country field.

 Last Modified: 
 Sep 07, 2012   PDI000      Initial version

*/
function getAbbrOfCountry(sCountry)
{
	var sAbbr = "";

	if (sCountry == COUNTRY_CA_E) // Canada
	{
		sAbbr = COUNTRY_ABBR_CA_E;
	}
	else if (sCountry == COUNTRY_US_E || sCountry == COUNTRY_US_F) // USA
	{
		sAbbr = COUNTRY_ABBR_US_E;
	}

	return sAbbr;
}


/**
 @function
 getAbbrOfProvState(sProvState)

 @description
 This function returns the abbreviation for the passed in Province or State and an empty
 string for anything else.  The processing is case-sensitive.

 @param {String} sProvState - the Province or State.

 @returns {String}           - the abbreviation of the Province or State or an empty string.

 @example
 Examples:
 var sAbbrProvState = CoreFunctions.getAbbrOfProvState(PartA_ProvState.rawValue);
 - gets the abbreviation of the value of the PartA_ProvState field.

 Last Modified: 
 Sep 11, 2012   PDI000      Initial version

*/
function getAbbrOfProvState(sProvState)
{
	var sAbbr = "";
	var nIdx = -1;
	// Check for Language
	if (getLanguage() == CoreMessages.LANG_FR)
	{
		// process for French
		if ((nIdx = PROV_ARRAY_F.indexOf(sProvState)) != -1) // Canadian Provinces
		{
			sAbbr = PROV_ABBR_ARRAY_F[nIdx];
		}
		else if ((nIdx = STATE_ARRAY_F.indexOf(sProvState)) != -1) // States
		{
			sAbbr = PROV_ABBR_ARRAY_F[nIdx];
		}
	}	
	else
	{
		// process for English
		if ((nIdx = PROV_ARRAY_E.indexOf(sProvState)) != -1) // Canadian Provinces
		{
			sAbbr = PROV_ABBR_ARRAY_E[nIdx];
		}
		else if ((nIdx = STATE_ARRAY_E.indexOf(sProvState)) != -1)
		{
			sAbbr = PROV_ABBR_ARRAY_E[nIdx];
		}
	}

	return sAbbr;
}


