/**
 @function
 diffDates(sFromDate, sToDate)

 @description
 This helper function calculates the number of days separating the two dates.

 @param {String} sFromDate - the first date.
 @param {String} sToDate - the second date.

 @returns {Number}       - how many days separate the 2 dates.

 @example
 Examples:
 if (CoreFunctions.diffDates(FromDate.rawValue, ToDate.rawValue) > 371)
    xfa.host.messageBox("The dates are greater than 371 days apart"); 
 - checks to see if the number of days separating the 2 dates is greater than 371 days. 

 Last Modified: 
 Mar 13, 2013   PDI000      Initial version

*/
function diffDates(sFromDate, sToDate)
{
	var dFrom = new Date(sFromDate.substring(0, 4), sFromDate.substring(4, 6), sFromDate.substring(6));
	var dTo = new Date(sToDate.substring(0, 4), sToDate.substring(4, 6), sToDate.substring(6));
	var nDaysDiff = (dTo.getTime() - dFrom.getTime())/86400000;

	return Math.abs(nDaysDiff);  // return the absolute value
}


/**
 @function
 handleRBClick(oField, sVal)

 @description
 This function allows a radio button to be deselected 

 @param {Node} oField                 - the radio button group object.
 @param {String} sVal                 - (optional) the value used to set the radio button group.

 @example
 Examples:
 handleRBClick(this);                 - usually used in the RB group's click event.
 handleRBClick(otherRBGroup, "1");    - used after setting another RB group's rawValue to "1".

 Last Modified: 
 Dec 24, 2013   DHC001      Initial version
 Mar 05, 2014   PDI000       Add a parameter which, when present, will be used to set the value of the radio button  

*/
var handleRBClick = function(){
	var rbs = new Object();
 	return function(o, sVal){
 		//console.println("IN RBClick o.rawValue |" + o.rawValue + "| and rbs |" + rbs[o.name] + "| and sVal |" + sVal + "|");
 		if (typeof sVal === "undefined")
 		{
	  		if (rbs[o.name] == o.rawValue) 
	  		{
	  			o.selectedMember().rawValue = null;
	  		}
	  		rbs[o.name] = o.rawValue; 
	  	}
	  	else
	  	{
	  		rbs[o.name] = sVal;	
	  	}
 	};
}();

