/**
 @function 
 getMessage(sMsg, sArg1, sArg2, sArg3, sArg4)

 @description
 This function looks up the requested message from the MESSAGES array and returns the message 
 using any of the optional arguments as message variables.

 @param {String} sMsg          - the message identifier without the language designation.
 @param	{String} sArg1-sArg4   - optional arguments to be inserted in the message where 
                                 format specifiers are found.

 @return {String}              - the message requested from the MESSAGES array.

 @example	
 Examples:
 CoreMessages.getMessage("M00001");
 - returns the message for M00001E or M00001F depending on the global language
 setting in CoreFunctions.LANGUAGE.

 CoreMessages.getMessage("M00009", "3", "27");
 - returns the message for M00009E or M00009F depending on the global language
 setting in CoreFunctions.LANGUAGE.  The message for M00009E is
 "An amount is required for Part %s Line %s.".  sArg1 and sArg2 will replace
 the "%s" variables so the result would be: 
 "An amount is required for Part 3 Line 27."

 Last Modified: 
 Apr 06, 2011    PDI000      Initial version
 Oct 21, 2011    PDI000      Check the Form Variable LANGUAGE to set the correct language
                             for the message string.			
 Sep 19, 2013    PDI000      Change argument insertion loop so that any extra sArg values
                             are ignored.

*/					
function getMessage(sMsg, sArg1, sArg2, sArg3, sArg4)
{
	var sRetMsg = "";
	var sMsgCode;

	try
	{	
		if (LANGUAGE.value.toLowerCase() == CoreFunctions.ENGLISH.toLowerCase())	// Add the language suffix based on the global variable
			sMsgCode = sMsg + LANG_EN;
		else if (LANGUAGE.value.toLowerCase() == CoreFunctions.FRENCH.toLowerCase())
			sMsgCode = sMsg + LANG_FR;
		else
		{
			xfa.host.messageBox("The LANGUAGE Form Variable value " + LANGUAGE.value + " is not recognized.\n\nPlease use recognized values only,  such as " +
				CoreFunctions.ENGLISH + " or " + CoreFunctions.FRENCH + ".", "Language Setting Error");
			sMsgCode = sMsg + LANG_EN;
		}

	}
	catch (err)
	{
		xfa.host.messageBox(err + "\n\nPlease use LANGUAGE as the Form Variable name.", "Javascript Exception");
		sMsgCode = sMsg + LANG_EN;
	}

	if(CoreFunctions.DEBUG) console.println(">>>>> In getMessage LANGUAGE is " +  LANGUAGE.value);		
	if(CoreFunctions.DEBUG) console.println(">>>>> Message code is " +  sMsgCode);

	if (sMsgCode.charAt(0) == "C")		// A message code beginning with C means we'll look in the custom messages
		sRetMsg = CustomMessages.MESSAGES[sMsgCode][0];
	else
		sRetMsg = MESSAGES[sMsgCode][0];	// otherwise we'll look in the core messages

	if (typeof sRetMsg != "undefined")
	{
		var sSplitMsg = sRetMsg.split("%s");

		if(CoreFunctions.DEBUG)
			console.println ("ARRAY len = " + sSplitMsg.length);

		var i;
		sRetMsg = sSplitMsg[0];
		for (i=1; i < sSplitMsg.length; i++)
		{

			if(CoreFunctions.DEBUG)
				console.println ("sSplitMsg " + i + " is " + sSplitMsg[i]);

			switch (i)
			{
				case 1:
					if(typeof sArg1 != "undefined")
						sRetMsg += sArg1;
					break;
				case 2:
					if(typeof sArg2 != "undefined")
						sRetMsg += sArg2;
					break;
				case 3:
					if(typeof sArg3 != "undefined")
						sRetMsg += sArg3;
					break;
				case 4:
					if(typeof sArg4 != "undefined")
						sRetMsg += sArg4;
					break;
			}
			sRetMsg += sSplitMsg[i];
		}
	}

	return sRetMsg;
}


/**
 @function
 getTitle(sMsg)

 @description
 This function looks up the requested message from the MESSAGES array and returns the title portion 
 of the data.

 @param {String} sMsg   - the message identifier without the language designation.
 @return {String}       - the title portion of the requested message.	

 @example
 Examples:
 CoreMessages.getTitle("M00001");
 - returns the title for M00001E or M00001F depending on the global language
   setting in CoreFunctions.LANGUAGE.

 Last Modified: 
 Apr 21, 2011   PDI000      Initial version
 Oct 21, 2011   PDI000      Check the Form Variable LANGUAGE to set the correct language
                            for the message string.			

*/
function getTitle(sMsg)
{
	var sRetMsg = "";
	var sMsgCode;

	try
	{
		if (LANGUAGE.value.toLowerCase() == CoreFunctions.ENGLISH.toLowerCase())	// Add the language suffix based on the global variable
			sMsgCode = sMsg + LANG_EN;
		else if (LANGUAGE.value.toLowerCase() == CoreFunctions.FRENCH.toLowerCase())
			sMsgCode = sMsg + LANG_FR;
		else
		{
			xfa.host.messageBox("The LANGUAGE Form Variable value " + LANGUAGE.value + " is not recognized.\n\nPlease use recognized values only,  such as " +
				CoreFunctions.ENGLISH + " or " + CoreFunctions.FRENCH + ".", "Language Setting Error");
			sMsgCode = sMsg + LANG_EN;
		}

	}
	catch (err)
	{
		xfa.host.messageBox(err + "\n\nPlease use LANGUAGE as the Form Variable name.", "Javascript Exception");
		sMsgCode = sMsg + LANG_EN;
	}

	if(CoreFunctions.DEBUG) console.println(">>>>> Message code is " +  sMsgCode);

	if (sMsgCode.charAt(0) == "C")		// A message code beginning with C means we'll look in the custom messages
		sRetMsg = CustomMessages.MESSAGES[sMsgCode][1];
	else
		sRetMsg = MESSAGES[sMsgCode][1];	// otherwise we'll look in the core messages

	if(CoreFunctions.DEBUG) console.println("|||||| sRetMsg is " +  sRetMsg);

	return sRetMsg;
}

