var gsAction= "";

function runDialog()
{
	Screen1();

	if (CustomFunctions.gsAction == "Elect")
	{
		setPermissions("1");
	}
	else
	{
		setPermissions("2");	
	}
}

function Screen1()
{ 
	var doc = this; //this is needed to control the scope for the nested functions.

	var sPrompt = "Select either Election or Revocation of Election.";
	var sCk01 = "Election";
	var sCk02 = "Revocation of Election";
	var sFini = "&Continue";

	if(LANGUAGE.value.toLowerCase() == CoreFunctions.FRENCH.toLowerCase())
	{
		sPrompt = "Choisissez le choix ou la révocation du choix.";
		sCk01 = "Choix";
		sCk02 = "Révocation du choix";
		sFini = "&Continuer";
	}

	var dialog =
	{ 
		initialize: function(dialog) 
		{ 
			CustomFunctions.gsAction= "Elect";
			dialog.load({ "ck01" : true});	
			dialog.load({ "ck02" : false});	

		}, //end initialize function

		"fini": function(dialog)
		{
			//TextField1.rawValue = CustomFunctions.globalVar; 
			dialog.end();
		},

		/////// load field values into PDFform on a field by field basis.
		"ck01": function(dialog)
		{
			var chkVal = dialog.store()["ck01"];
			//console.println("chkVal is " + chkVal);
			if(chkVal)
			{
				CustomFunctions.gsAction= "Elect";
				dialog.load({ "ck01" : true});
				dialog.load({ "ck02" : false});
			}
		},

		"ck02": function(dialog)
		{
			var chkVal = dialog.store()["ck02"];
			if(chkVal)
			{
				CustomFunctions.gsAction= "Revoke";
				dialog.load({ "ck02" : true});
				dialog.load({ "ck01" : false});	
			}
		},

	//////////////////////// The Dialog Description ///////////////////////
		description:
		{ 
			name: "T1226", elements:
			[{ type: "view", align_children: "align_left", elements: 
				[{ type: "view", align_children: "align_distribute", elements: 
					[{ type: "static_text", name: sPrompt},]},
				{ type: "view", align_children: "align_distribute", elements: 
					[{ type: "check_box", char_width: 10, item_id: "ck01", name: sCk01},]},
				{ type: "view", align_children: "align_distribute", elements: 
					[{ type: "check_box", char_width: 10, item_id: "ck02", name: sCk02},]},								
				{ type: "view", align_children: "align_distribute", elements: 
					[{ type: "button", name: sFini, item_id: "fini"},]},
				]},
			]},
		}; 	

	app.execDialog(dialog);	
	return dialog.result;
}

function setPermissions(sAction)
{
	if (sAction == "1") // Elect
	{
		F.Page1.DialogState.rawValue = "1";

		Page1.PartC.ElectionOrRevocation_ChkBox.rawValue = "1";
		Page1.PartC.ElectionOrRevocation_ChkBox.access = "readOnly";
		Page1.PartC.PartC_Electiondate.access = "open";		
		CoreFunctions.setRequired(F.Page1.PartC.PartC_Electiondate, true);

		//disable and clear revocation fields		
		F.Page1.PartD.ElectionOrRevocation_ChkBox.access = "protected";
		F.Page1.PartD.ElectionOrRevocation_ChkBox.rawValue = "0";

		CoreFunctions.setRequired(F.Page1.PartD.PartD_RevocationDate, false);
		F.Page1.PartD.PartD_RevocationDate.access = "protected";

	}
	else // Revoke
	{
		F.Page1.DialogState.rawValue = "2";

		F.Page1.PartD.ElectionOrRevocation_ChkBox.access = "readOnly";
		F.Page1.PartD.ElectionOrRevocation_ChkBox.rawValue = "1";

		CoreFunctions.setRequired(F.Page1.PartD.PartD_RevocationDate, true);
		F.Page1.PartD.PartD_RevocationDate.access = "open";


		Page1.PartC.ElectionOrRevocation_ChkBox.rawValue = "0";
		Page1.PartC.ElectionOrRevocation_ChkBox.access = "protected";
		Page1.PartC.PartC_Electiondate.access = "protected";		
		CoreFunctions.setRequired(F.Page1.PartC.PartC_Electiondate, false);	}
}


