/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
// ProcessAllFields Function
/////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

// Process all fields found within the specified node (object).
// For each field that's found, the appropriate Field Processor Function
//  is called with a reference to the field itself.
function ProcessAllFields(oNode, sPermission)
{
	if (oNode.className == "exclGroup" || oNode.className == "subform"  || oNode.className == "subformSet" || oNode.className == "area")
	{
		// Look for child fields.

		for (var i = 0; i < oNode.nodes.length; i++)
		{
			var oChildNode = oNode.nodes.item(i);
			ProcessAllFields(oChildNode, sPermission);
		}
	}
	else if (oNode.className == "field")
	{
		switch (oNode.ui.oneOfChild.className)
		{
			case "button":
				ProcessButton(oNode, sPermission);
				break;

			case "checkButton":
				if (oNode.parent.className == "exclGroup")
				{
					// checkButtons inside exclusion groups are radio buttons
					ProcessRadioButton(oNode, sPermission);
				}
				else
				{
					// otherwise, they're check boxes
					ProcessCheckBox(oNode, sPermission);
				}
				break;

			case "choiceList":
			{
				var oUITypeNode = oNode.ui.resolveNode("#choiceList");

				if (oUITypeNode.open == "userControl")
				{
					// drop down list / combo box
					ProcessDropDownList(oNode, sPermission);
				}
				else
				{
					// otherwise, it's a list box
					ProcessListBox(oNode, sPermission);
				}

				break;
			}

			case "dateTimeEdit":
				ProcessDateTime(oNode, sPermission);
				break;

			case "imageEdit":
				ProcessImageEdit(oNode, sPermission);
				break;

			case "numericEdit":
				ProcessNumeric(oNode, sPermission);
				break;

			case "passwordEdit":
				ProcessPassword(oNode, sPermission);
				break;

			case "textEdit":
				ProcessTextEdit(oNode, sPermission);
				break;

			case "signature":
				ProcessSignature(oNode, sPermission);
				break;

			case "barcode":
				ProcessBarcodeEdit(oNode, sPermission);
				break;

			default:
				// unknown field type
				break;
		}
	}
}

